# Category edition two: each subject has an independent introduction, useful paths and reading guide.
CATEGORY_V2 = {
 'menesa-kalendars'=>{style:'paper',photo:'monthly',line:'Vieta visam, kas gaidāms.',cta:'Plānot mēnesi',facts:[['48','mēnešu pārskati'],['15','drukas dizaini'],['P–Sv','Latvijas kalendārs']],faq:[['Vai mani notikumi nonāk izdrukā?','Jā. PDF un attēls ietver izvēlētā skata redzamos notikumus un dienas piezīmes. Garākas piezīmes turpinās pielikumā.'],['Ar ko atšķiras Excel un ICS?','Excel ir rediģējama izvēlētā perioda tabula. ICS pārvieto personīgos notikumus uz citu kalendāru.'],['Kā atvērt konkrētu dienu?','Spied uz datuma. Dienas panelī vari rakstīt piezīmi vai pievienot notikumu.']]},
