 'gimenes-kalendars'=>{style:'family',photo:'family',line:'Kopīgs skats uz jūsu nedēļu.',cta:'Sākt ģimenes plānu',facts:[['8','ģimenes locekļi'],['7','dienu ēdienkarte'],['ICS','notikumu eksports']],faq:[['Vai kalendārs sinhronizējas ģimenes telefonos?','Ieraksti glabājas šajā pārlūkā. Pārvietošanai izmanto JSON dublējumu; ICS fails paredzēts notikumu importam citā kalendārā.'],['Kā izveidot pirkumu sarakstu?','Maltītei pievieno sastāvdaļas, atdalot tās ar komatiem. Produktus vari pievienot un atzīmēt arī atsevišķi.'],['Vai atkārtojumu var ierobežot?','Jā. Nedēļas notikumam norādi atkārtojuma pēdējo dienu. Bez tās notikums turpinās katru nedēļu.']]},
 'atvalinajuma-planotajs'=>{style:'escape',photo:'jurmala',line:'Vairāk laika atpūtai Latvijā.',cta:'Aprēķināt savu atvaļinājumu',facts:[['2027–2030','plānošanas gadi'],['Tavs','dienu budžets'],['LV','svētku datumi']],faq:[['Vai ieteikums jau ir apstiprināts atvaļinājums?','Nē. Tas ir aprēķins pēc izvēlētā darba grafika un svētku brīvdienām. Datumi jāsaskaņo ar darba devēju.'],['Vai sešu dienu darba nedēļa dod citu rezultātu?','Jā. Atvaļinājuma darba dienas tiek skaitītas pēc izvēlētā grafika. Papildu brīvās vai darba dienas ievadi iestatījumos.'],['Vai kopējā plānā dienas var ieskaitīt divreiz?','Izvēlētie periodi nedrīkst pārklāties. Plānotājs saskaita izmantoto atvaļinājuma budžetu vienam gadam.']]},
 'mainu-grafiks'=>{style:'shift',photo:'clock',line:'Diena. Nakts. Brīvs.',cta:'Veidot maiņu ciklu',facts:[['31','diena ciklā'],['D / N','dienas un nakts maiņas'],['CSV','tabula darbam']],faq:[['Kurā datumā ieskaita nakts maiņu?','Maiņa pieder tās sākuma datumam. Ja beigu laiks nav vēlāk par sākuma laiku, beigas ir nākamajā dienā.'],['Vai konkrētu datumu var mainīt, nepārrakstot ciklu?','Jā. Atlasot dienu, saglabā izņēmumu. Atjaunot ciklu atceļ tikai šīs dienas labojumu.'],['Vai darba stundās ieskaita pārtraukumu?','No maiņas ilguma atņem norādīto pārtraukumu. Šis ir personīgs grafiks; darba un atpūtas laika prasības pārbaudi atsevišķi.']]},
 'varda-dienas'=>{style:'names',photo:'flowers',line:'Mazs datums. Liels prieks.',cta:'Atrast vārda dienu',facts:[['1 032','tradicionālie ieraksti'],['4 620','papildu ieraksti'],['VVC','oficiālais avots']],faq:[['Vai Jānis un Janis ir viens ieraksts?','Nē. Saglabājam VVC avota rakstību. Meklēšana bez garumzīmēm palīdz atrast abus, bet datumi un saraksta veids paliek atsevišķi.'],['Ko nozīmē paplašinātais saraksts?','Tas ietver papildu kalendārvārdus. Tradicionālais un paplašinātais saraksts ir skaidri atzīmēts katrā rezultātā.'],['Vai var saglabāt atlasīto vārdu datumus?','Jā. Izvēlies gadu un filtrus, tad lejupielādē atlasīto datumu ICS failu.']]},
 'svetki-un-tradicijas'=>{style:'stories',photo:'ligo',line:'Latvijas gads dzīvos stāstos.',cta:'Iepazīt datumus un tradīcijas',facts:[['Latvija','gadskārtas un tradīcijas'],['Atsevišķi','brīvdienu statuss'],['Avoti','pie katras tēmas']],faq:[['Vai visas šīs dienas ir brīvdienas?','Nē. Svētku brīvdienas, atceres dienas, atzīmējamās dienas un kultūras tradīcijas ir dažādas kategorijas. Izmanto veida filtru.'],['Kāpēc Meteņiem nav viena datuma visiem gadiem?','Avoti un novadu tradīcijas atšķiras. Konkrētu pasākumu datumus izziņo rīkotāji; tos nepārceļam no iepriekšējiem gadiem.'],['Vai lejupielādē ietilpst visi tēmas datumi?','ICS failā ietilpst tikai izvēlētajam gadam un mēnesim atbilstošie, pārbaudāmie datumi.']]},
 'skolas-brivlaiki'=>{style:'school',photo:'school',line:'Mācību gads ar skaidriem datumiem.',cta:'Skatīt skolu brīvlaikus',facts:[['1.–12.','klašu datumi'],['11','valsts augstskolas'],['MK 768','publicētais skolu grafiks']],faq:[['Vai skolu un augstskolu brīvdienas sakrīt?','Augstskolas publicē patstāvīgus akadēmiskos kalendārus. To studiju un eksāmenu periodi tiek rādīti atsevišķi no brīvlaikiem.'],['Kāpēc nākamā mācību gada datumi var nebūt redzami?','Ja nav publicēts oficiāls grafiks, iepriekšējā gada datumus nepārceļam. Avota statuss ir norādīts pie gada.'],['Vai var izvēlēties savu klasi?','Jā. Izlaiduma klašu mācību gada beigas atšķiras; 1. klases papildu brīvdienu nedēļu nosaka pati skola.']]},
 'stundu-saraksts'=>{style:'timetable',photo:'ring-planner',line:'Vairāk skaidrības katrai mācību dienai.',cta:'Veidot savu stundu sarakstu',facts:[['7','nedēļas dienas'],['15','drukas dizaini'],['Pārbaude','stundu pārklāšanās']],faq:[['Vai stundas tiek atkārtotas automātiski?','Jā, izvēlētajā nedēļas dienā no perioda sākuma līdz beigām. Skolas brīvlaiks netiek izslēgts automātiski.'],['Kā tiek pārbaudīta pārklāšanās?','Salīdzina stundas laiku un faktiskos kopīgos datumus norādītajos mācību periodos. Stundas ar kopīgu robežlaiku nepārklājas.'],['Vai izdrukā būs arī skolotājs un telpa?','Jā. Ja šie lauki aizpildīti, tie tiek iekļauti nedēļas PDF un attēlā kopā ar stundas laiku un priekšmetu.']]},
 'visi-riki'=>{style:'directory',photo:'desk-tools',line:'Tavs nākamais plāns sākas te.',cta:'Izvēlēties rīku',facts:[['24','rīki vienuviet'],['5','uzdevumu grupas'],['Saglabā','savus iecienītos']],faq:[['Vai nepieciešams konts?','Personīgos kalendārus un plānotājus var lietot bez konta. Ieraksti un saglabātie rīki paliek šajā pārlūkā.'],['Kā atrast piemērotu rīku?','Meklē pēc nosaukuma vai izvēlies uzdevumu: kalendāri, personīgie plāni, darbs, mācības vai daba.'],['Kur atrast saglabātos rīkus?','Atzīmē rīka kartīti ar saglabāšanas pogu un ieslēdz filtru Mani saglabātie.']]},
 'saullekts-saulriets'=>{style:'sun',photo:'summer',line:'Seko gaismai savā pilsētā.',cta:'Izpētīt Saules ceļu',facts:[['82','Latvijas pilsētas'],['Europe/Riga','vietējais laiks'],['Gada līkne','dienas garuma salīdzinājums']],faq:[['Vai laiks mainās, izvēloties citu pilsētu?','Jā. Saullēkts, saulriets un krēsla ir atkarīgi no koordinātām. Laika josla visā Latvijā ir viena.'],['Kāpēc aiz loga Saule pazūd citā laikā?','Aprēķins izmanto standarta horizontu. Ēkas, mežs, reljefs un atmosfēras apstākļi var mainīt faktisko redzamību.'],['Ko rāda gada līkne?','Katra mēneša 21. datuma dienas garumu izvēlētajā pilsētā. Tā palīdz salīdzināt gadalaikus, nevis prognozē laikapstākļus.']]},
 'meness-kalendars'=>{style:'lunar',photo:'moon',line:'Tuvāk Mēnesim. Dienu pēc dienas.',cta:'Izvēlēties Mēness mēnesi',facts:[['48','mēneši 2027–2030'],['12.00','dienas attēla Latvijas laiks'],['4','veidnes katram periodam']],faq:[['Vai redzamais Mēness ir nākotnes fotogrāfija?','Nē. Dienas attēls ir aprēķināta ilustrācija ar īstu NASA LRO virsmas karti. Gadu vākiem izmantotas arhīva misiju fotogrāfijas.'],['Vai kalendārs paredzēts visai Latvijai?','Jā. Šis ir ģeocentrisks fāžu pārskats pēc Latvijas laika. Vietējais Mēness lēkts un riets ir atsevišķā pilsētu rīkā.'],['Kā apskatīt konkrētu dienu?','Atver mēneša lapu un spied uz datuma. Atlasītās dienas panelī redzams palielināts disks un apgaismojums.']]},
 'meness-fazes'=>{style:'phases',photo:'moon',line:'Četri precīzi mirkļi katrā ciklā.',cta:'Atrast fāzes datumu',facts:[['USNO','galveno fāžu brīži'],['4','fāžu veidi'],['UTC + LV','pārbaudāmi laiki']],faq:[['Vai pilnmēness ilgst visu dienu?','Astronomiskais pilnmēness ir noteikts brīdis. Acīm disks var izskatīties gandrīz pilns arī blakus naktīs.'],['Kāpēc pie laika redzams arī UTC?','UTC ir avota laiks. Latvijas pulksteņa laiks pārrēķināts Europe/Riga joslā, ievērojot vasaras un ziemas laiku.'],['Vai fāzes brīdis atkarīgs no pilsētas?','Galvenās fāzes brīdis ir kopīgs visai pasaulei. Vietējais Mēness augstums, lēkts un riets gan atšķiras.']]},
 'gadalaiki'=>{style:'seasons',photo:'autumn',line:'Četras sezonas. Viena Latvija.',cta:'Apskatīt gadalaiku sākumu',facts:[['4','astronomiskie sākumi'],['3','gadalaiku iedalījumi'],['2027–2030','pārbaudāmi brīži']],faq:[['Vai astronomiskais pavasaris vienmēr sākas 21. martā?','Nē. Ekvinokcijas brīdis katru gadu tiek aprēķināts atsevišķi un pārrēķināts Latvijas laikā.'],['Ar ko atšķiras kalendārais un astronomiskais gadalaiks?','Kalendārais iedalījums sākas mēneša pirmajā datumā; astronomiskais — ekvinokcijas vai saulgriežu brīdī.'],['Vai meteoroloģiskajai ziemai ir fiksēts sākuma datums?','Nē. Latvijas temperatūras gadalaiki atkarīgi no faktiskās vidējās gaisa temperatūras gaitas.']]},
 'astronomiskais-kalendars'=>{style:'cosmos',photo:'earth',line:'Latvijas debesis vienā kalendārā.',cta:'Plānot novērošanas vakaru',facts:[['82','pilsētu redzamība'],['5','notikumu grupas'],['ICS','debesu notikumu plāns']],faq:[['Vai katrs saraksta aptumsums būs redzams Latvijā?','Nē. Pie aptumsuma atsevišķi norādīts aprēķins izvēlētajai pilsētai. Globālais notikums un vietējā redzamība ir dažādas lietas.'],['Ko nozīmē Perseīdu novērošanas logs?','Tas ir tumšās nakts plānošanas periods izvēlētajā pilsētā. Tas negarantē meteoru skaitu, maksimumu vai skaidru laiku.'],['Vai ICS fails atjaunojas pats?','Nē. Tas ir izvēlēto notikumu eksports vienā brīdī. Ja maini pilsētu, gadu vai filtrus, saglabā jaunu failu.']]}
