def v2_photo(id,klass='',alt='')
 mapped={'monthly'=>'calendar','weekly'=>'week','ring-planner'=>'planner','desk-tools'=>'alltools','clock'=>'shift','flowers'=>'names','family'=>'family','ligo'=>'culture','school'=>'school','summer'=>'sunrise','winter'=>'moon','autumn'=>'seasons','jurmala'=>'vacation','independence'=>'names'}.fetch(id,id)
 %(<img class="#{klass} v2-illustration" src="/assets/category-vector/#{mapped}.svg?v={{ site.data.build.asset_version }}" alt="#{h(alt)}" width="640" height="520" decoding="async">)
end

def v2_calendar_scene(week=false)
 first=Date.new(2027,1,1)
 if week
  start=Date.commercial(2027,1,1)
  days=(0..6).map{|i|d=start+i;%(<a href="/nedelas-kalendars/?date=#{d}&amp;view=week"><small>#{DAYS[i]}</small><b>#{d.day}</b><span class="v2-week-line"></span><span class="v2-week-line short"></span></a>)}.join
  %(<div class="v2-paper v2-week-paper"><span class="v2-paper-kicker">NEDĒĻAS PLĀNS · 2027</span><strong>4.–10. janvāris</strong><div class="v2-week-preview">#{days}</div><span class="v2-paper-foot">ISO 01 <span>PIRMDIENA–SVĒTDIENA</span></span></div>)
 else
  cells=Array.new(first.cwday-1,'<span></span>')+(1..31).map{|d|date=Date.new(2027,1,d);%(<a #{date.cwday>5||d==1 ? 'class="off"' : ''} href="/menesa-kalendars/?date=#{date}&amp;view=month" aria-label="#{d}. janvāris 2027">#{d}</a>)}
  %(<div class="v2-paper v2-month-paper"><span class="v2-paper-kicker">TAVS GADS, TAVI PLĀNI</span><strong>Janvāris <em>2027</em></strong><div class="v2-mini-calendar">#{DAYS.map{|d|"<small>#{d}</small>"}.join}#{cells.join}</div><span class="v2-paper-foot">KALENDĀRS365 <span>LATVIJA</span></span></div>)
 end
end

def category_v2_scene(slug,cfg)
 case slug
 when 'menesa-kalendars','nedelas-kalendars'
  v2_photo(cfg[:photo],'v2-scene-backdrop')+v2_calendar_scene(slug=='nedelas-kalendars')
 when 'gimenes-kalendars'
  v2_photo('family','v2-scene-photo')+'<div class="v2-floating-note"><span class="v2-paper-kicker">JŪSU KOPĪGAIS PLĀNS</span><strong>Katram sava krāsa.</strong><div class="v2-people-colors"><i></i><i></i><i></i><i></i><i></i></div><span>Notikumi · maltītes · pirkumi</span></div>'
 when 'stundu-saraksts'
  v2_photo('ring-planner','v2-scene-photo')+'<div class="v2-floating-note"><span class="v2-paper-kicker">MĀCĪBU NEDĒĻA</span><strong>Priekšmets. Telpa. Laiks.</strong><div class="v2-subject-bars"><i></i><i></i><i></i></div><span>Tavs saraksts, bez izdomātām stundām.</span></div>'
 when 'mainu-grafiks'
  v2_photo('clock','v2-scene-backdrop')+'<div class="v2-shift-wheel"><span class="v2-paper-kicker">IZVĒLIES SAVU RITMU</span><strong>D / N / B / B</strong><div><span>Diena</span><span>Nakts</span><span>Brīvs</span><span>Brīvs</span></div><p>Maiņu secības piemērs</p></div>'
 when 'varda-dienas'
  v2_photo('flowers','v2-scene-photo')+'<div class="v2-name-letter"><span class="v2-paper-kicker">VĀRDA DIENAS LATVIJĀ</span><strong>Atceries<br>savējos.</strong><a href="#category-workspace">Atrast vārdu <span>↗</span></a></div>'
 when 'meness-kalendars'
  photo = lunar_cover(2027)
  %(<figure class="v2-lunar-photograph"><img src="#{h(photo.fetch('src'))}?v={{ site.data.build.asset_version }}" alt="#{h(photo.fetch('alt'))}" width="#{photo.fetch('width')}" height="#{photo.fetch('height')}" fetchpriority="high" decoding="async"><figcaption>#{h(photo.fetch('credit'))} · 19.12.1972. <span>#{a(photo.fetch('source'),'Foto avots')} · #{a('/pilsetas-un-fotografijas/#astronomijas-fotografijas','Izmantošanas noteikumi')}</span></figcaption></figure>)
 when 'meness-fazes'
  '<div class="v2-phase-arc">'+%w[new first full last].each_with_index.map{|phase,i|%(<div><img src="/assets/category-vector/phase-#{phase}.svg" alt="" width="160" height="160"><small>#{['Jaunmēness','Pirmais ceturksnis','Pilnmēness','Pēdējais ceturksnis'][i]}</small></div>)}.join+'</div><span class="v2-mission-label">Mēness cikls · ilustratīvs zīmējums</span>'
 when 'astronomiskais-kalendars'
  '<div class="v2-earth-orbit"><img src="/assets/category-vector/earth.svg" width="400" height="400" alt=""><img src="/assets/category-vector/moon.svg" width="130" height="130" alt=""></div><span class="v2-mission-label">Zeme un Mēness · ilustratīvs mērogs</span>'
 when 'gadalaiki'
  '<div class="v2-season-illustration"><img src="/assets/category-vector/seasons.svg" alt="" width="640" height="520"><div><span>Pavasaris</span><span>Vasara</span><span>Rudens</span><span>Ziema</span></div></div>' 
 when 'saullekts-saulriets'
  v2_photo('summer','v2-scene-photo')+'<div class="v2-solar-arc" aria-hidden="true"><svg viewBox="0 0 500 260"><defs><linearGradient id="v2-sun-g"><stop stop-color="#ffe9ae"/><stop offset="1" stop-color="#d69b4f"/></linearGradient></defs><path d="M40 210Q250 -130 460 210" fill="none" stroke="#fff4d7" stroke-width="2" stroke-dasharray="4 7"/><path d="M35 211H465" stroke="#fff4d7" stroke-width="1"/><circle cx="250" cy="40" r="20" fill="url(#v2-sun-g)"/></svg></div><span class="v2-mission-label">Saules ceļš · ilustratīvs zīmējums</span>'
 when 'skolas-brivlaiki'
  v2_photo('school','v2-scene-photo')+'<a class="v2-floating-note" href="#augstskolas"><span class="v2-paper-kicker">SKOLAS UN AUGSTSKOLAS</span><strong>Katram savs kalendārs.</strong><span>Klases · brīvlaiki · studiju periodi ↗</span></a>'
 when 'visi-riki'
  '<div class="v2-tools-mosaic">'+[['calendar','/menesa-kalendars/','Kalendāri'],['family','/gimenes-kalendars/','Tavi plāni'],['school','/skolas-brivlaiki/','Mācības'],['astronomy','/astronomiskais-kalendars/','Daba']].map{|image,url,title|%(<a href="#{url}"><img src="/assets/category-vector/#{image}.svg" alt="" width="100" height="90"><strong>#{title}</strong><span>↗</span></a>)}.join+'</div>'
 when 'svetki-un-tradicijas'
  v2_photo('ligo','v2-scene-photo')+'<div class="v2-story-tag"><span>LATVIJAS GADSKĀRTAS</span><strong>No Jāņiem<br>līdz Ziemassvētkiem.</strong></div>'
