def category_hero_markup(slug,heading)
 cfg=CATEGORY_V2.fetch(slug);info=CATEGORY_EXPERIENCES.fetch(slug);links=info[4..-1].map{|l|l.split('|',2)}
 if %w[menesa-kalendars nedelas-kalendars gimenes-kalendars stundu-saraksts mainu-grafiks].include?(slug)
  existing=links.find{|label,url|label=='Drukas dizaini'}
  if existing;existing[1]='#v2-designs';else links << ['Drukas dizaini','#v2-designs'];end
 end
 nav=links.each_with_index.map{|(label,url),i|%(<a href="#{url}"><span>#{format('%02d',i+1)}</span>#{h(label)}<b aria-hidden="true">↗</b></a>)}.join
 %(<header class="v2-hero v2-hero--#{cfg[:style]}"><div class="v2-hero-copy"><span class="eyebrow">#{h(info[1])}</span><h1>#{h(heading)}</h1><p class="v2-hero-line">#{h(cfg[:line])}</p><p class="v2-hero-description">#{h(info[3])}</p><a class="v2-primary" href="#{links.first.last}">#{h(cfg[:cta])}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a><div class="v2-hero-facts">#{cfg[:facts].map{|value,label|"<div><strong>#{h(value)}</strong><span>#{h(label)}</span></div>"}.join}</div></div><div class="v2-hero-scene">#{category_v2_scene(slug,cfg)}</div></header><nav class="v2-section-nav" aria-label="Šīs lapas sadaļas">#{nav}<a href="#v2-answers"><span>?</span>Jautājumi un atbildes<b aria-hidden="true">↓</b></a></nav>)
end

def category_v2_finish(slug,body)
 # Preserve the working data attributes; rebuild the ordering and surrounding information.
 if %w[gimenes-kalendars stundu-saraksts].include?(slug)
  body=body.sub(/<header class="organizer-hero.*?<\/header>/m,'')
  week=body[/<section class="organizer-card organizer-week-card">.*?<\/section>/m]
  if week
   body=body.sub(week,'');body=body.sub(/(<\/section>)/, '\\1'+week)
  end
 end
 guide=body[/<section class="category-guide" id="category-guide">.*?<\/section>/m]
 body=body.sub(guide,'') if guide
 if %w[menesa-kalendars nedelas-kalendars gimenes-kalendars stundu-saraksts mainu-grafiks].include?(slug)
  kind=%w[menesa-kalendars nedelas-kalendars].include?(slug) ? 'period' : {'gimenes-kalendars'=>'family','stundu-saraksts'=>'school','mainu-grafiks'=>'shift'}[slug]
  body+=%(<section class="v2-design-studio" id="v2-designs" data-v2-designs="#{kind}"><div class="v2-block-heading"><div><span class="eyebrow">TAVS PLĀNS UZ PAPĪRA</span><h2>15 veidi, kā izskatās tavs kalendārs.</h2><p>Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.</p></div><span class="v2-format-tag">A4 · 600 ppi</span></div><div class="v2-design-grid" data-v2-design-grid></div><p data-v2-design-status role="status"></p><dialog class="v2-preview-dialog" data-v2-preview aria-label="Kalendāra priekšskatījums"><div class="v2-preview-bar"><strong data-v2-preview-title></strong><button type="button" data-v2-preview-close aria-label="Aizvērt priekšskatījumu">×</button></div><div data-v2-preview-content></div><div class="v2-preview-downloads"><button type="button" data-v2-download="pdf"><img src="/assets/file-pdf.svg" width="24" height="24" alt="">PDF ↓</button><button type="button" data-v2-download="webp"><img src="/assets/file-image.svg" width="24" height="24" alt="">Attēls ↓</button><span data-v2-preview-status role="status"></span></div></dialog></section>)
 end
 body+=guide if guide
 faq=CATEGORY_V2.fetch(slug).fetch(:faq)
 body+%(<section class="v2-answers" id="v2-answers"><div><span class="eyebrow">NODER ZINĀT</span><h2>Atbildes pirms nākamā plāna.</h2><p>Latvijas datumi, skaidri pieņēmumi un tavas izvēles.</p><a href="/avoti-un-metodika/">Avoti un aprēķinu metodika ↗</a></div><div>#{faq.map{|q,answer|"<details><summary>#{h(q)}<span aria-hidden=\"true\">+</span></summary><p>#{h(answer)}</p></details>"}.join}</div></section><p class="v2-photo-source"><a href="/pilsetas-un-fotografijas/#category-vectors">Ilustrāciju autortiesības un fotogrāfiju avoti ↗</a></p>)
end
